"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/spinner.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type SpinnerProps = ComponentPropsWithRef<"span"> & {
  size?: "small" | "medium" | "large";
  label?: string;
};

export function Spinner({ className, size = "medium", label = "Loading", ...props }: SpinnerProps) {
  return <span className={cn("whatiuse-loading-spinner", `whatiuse-loading-spinner--${size}`, className)} role="status" aria-label={label} {...props}><span aria-hidden="true" /></span>;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-loading-spinner { display: inline-grid; place-items: center; color: currentColor; }

.whatiuse-loading-spinner > span { width: 100%; height: 100%; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: whatiuse-spin 620ms linear infinite; }

@media (prefers-reduced-motion: reduce) {
.whatiuse-loading-spinner > span { animation-duration: 2.4s; }
}

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
